package net.civeira.phylax.feature.observe.observeddashboard.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject.BuiltinVO;

class BuiltinValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of builtin of observed dashboard")
  void test_builtin_value_holder_assign_plain_value() {
    Object holder = new Object();
    BuiltinValueHolder<Object> value = new BuiltinValueHolder<>(holder);
    Assertions.assertSame(holder, value.builtin(true), "Setters must return the holder");
    Assertions.assertTrue(value.getBuiltinValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getBuiltin().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of builtin of observed dashboard")
  void test_builtin_value_holder_assign_value_object() {
    Object holder = new Object();
    BuiltinValueHolder<Object> value = new BuiltinValueHolder<>(holder);
    BuiltinVO vo = BuiltinVO.from(true);
    Assertions.assertFalse(value.getBuiltinValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.builtin(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getBuiltinValue().orElseThrow());
    Assertions.assertSame(holder, value.builtin(Optional.empty()));
    Assertions.assertFalse(value.getBuiltinValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.builtin(Optional.of(vo)));
    Assertions.assertSame(vo, value.getBuiltinValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of builtin of observed dashboard against the original")
  void test_builtin_value_holder_read() {
    Object holder = new Object();
    BuiltinValueHolder<Object> value = new BuiltinValueHolder<>(holder);
    BuiltinVO vo = BuiltinVO.from(true);
    BuiltinVO other = BuiltinVO.from(true);
    ObservedDashboard original = Mockito.mock(ObservedDashboard.class);
    Mockito.when(original.getBuiltinValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readBuiltin(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readBuiltin(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.builtin(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readBuiltin(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readBuiltin(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of builtin of observed dashboard")
  void test_builtin_value_holder_unset() {
    Object holder = new Object();
    BuiltinValueHolder<Object> value = new BuiltinValueHolder<>(holder);
    BuiltinVO vo = BuiltinVO.from(true);
    value.builtin(vo);
    Assertions.assertSame(holder, value.unsetBuiltinIfMatches("builtin_other"));
    Assertions.assertTrue(value.getBuiltinValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetBuiltinIfMatches("builtin"));
    Assertions.assertFalse(value.getBuiltinValue().isPresent(),
        "The field name must clear the value");
    value.builtin(vo);
    Assertions.assertSame(holder, value.unsetBuiltin());
    Assertions.assertFalse(value.getBuiltinValue().isPresent(), "Unset must clear the value");
  }
}
